"""Kaleidoscope MCP Server — expose paper-intelligence capabilities via Model Context Protocol.

This server uses stdio transport and exposes Kaleidoscope's agent tools
as MCP tools that can be called by Claude, GPT, and other LLM agents.

Usage:
    python -m app.mcp_server

Environment variables:
    KALEIDOSCOPE_URL      — Backend base URL (default: http://127.0.0.1:8000)
    KALEIDOSCOPE_API_KEY  — API key for authentication (default: sk-kaleidoscope)
"""

from __future__ import annotations

import json
import os
from collections.abc import Sequence
from typing import Any

import httpx
from mcp.server import Server
from mcp.server.stdio import stdio_server
from mcp.types import Resource, TextContent, Tool

# ─── Configuration ──────────────────────────────────────────────────────────

KALEIDOSCOPE_URL = os.environ.get("KALEIDOSCOPE_URL", "http://127.0.0.1:8000")
KALEIDOSCOPE_API_KEY = os.environ.get("KALEIDOSCOPE_API_KEY", "sk-kaleidoscope")

server = Server("kaleidoscope")

# ─── HTTP Client Helper ─────────────────────────────────────────────────────


def _headers() -> dict[str, str]:
    return {"X-API-Key": KALEIDOSCOPE_API_KEY, "Content-Type": "application/json"}


async def _api_get(path: str, params: dict[str, Any] | None = None) -> dict[str, Any]:
    """Make a GET request to the Kaleidoscope API."""
    async with httpx.AsyncClient(base_url=KALEIDOSCOPE_URL, timeout=120.0) as client:
        resp = await client.get(path, headers=_headers(), params=params)
        resp.raise_for_status()
        result: dict[str, Any] = resp.json()
        return result


async def _api_post(path: str, body: dict[str, Any] | None = None) -> dict[str, Any]:
    """Make a POST request to the Kaleidoscope API."""
    async with httpx.AsyncClient(base_url=KALEIDOSCOPE_URL, timeout=120.0) as client:
        resp = await client.post(path, headers=_headers(), json=body or {})
        resp.raise_for_status()
        result: dict[str, Any] = resp.json()
        return result


