@server.list_tools()  # type: ignore[no-untyped-call, untyped-decorator]
async def handle_list_tools() -> list[Tool]:
    """Return all available tools."""
    return TOOL_DEFINITIONS


@server.call_tool()  # type: ignore[no-untyped-call, untyped-decorator]
async def handle_call_tool(name: str, arguments: dict[str, Any]) -> Sequence[TextContent]:
    """Dispatch a tool call to the Kaleidoscope REST API."""
    try:
        result = await _dispatch_tool(name, arguments)
        return [TextContent(type="text", text=json.dumps(result, ensure_ascii=False))]
    except httpx.HTTPStatusError as exc:
        error_body = exc.response.text[:1000]
        return [
            TextContent(
                type="text",
                text=json.dumps(
                    {
                        "error": f"HTTP {exc.response.status_code}",
                        "detail": error_body,
                    }
                ),
            )
        ]
    except httpx.RequestError as exc:
        return [
            TextContent(
                type="text",
                text=json.dumps(
                    {
                        "error": "connection_error",
                        "detail": f"Could not reach Kaleidoscope API at {KALEIDOSCOPE_URL}: {exc}",
                    }
                ),
            )
        ]
    except Exception as exc:
        return [
            TextContent(
                type="text",
                text=json.dumps({"error": "internal_error", "detail": str(exc)}),
            )
        ]


async def _dispatch_tool(name: str, arguments: dict[str, Any]) -> Any:
    """Route tool calls to the appropriate Kaleidoscope API endpoint."""
    api = "/api/v1"

    if name == "search_papers":
        return await _api_post(
            f"{api}/agent/call", {"tool": "search_papers", "arguments": arguments}
        )

    elif name == "get_paper":
        return await _api_post(f"{api}/agent/call", {"tool": "get_paper", "arguments": arguments})

    elif name == "get_citations":
        return await _api_post(
            f"{api}/agent/call", {"tool": "get_citations", "arguments": arguments}
        )

    elif name == "find_similar":
        return await _api_post(
            f"{api}/agent/call", {"tool": "find_similar", "arguments": arguments}
        )

    elif name == "summarize_paper":
        return await _api_post(
            f"{api}/agent/call", {"tool": "summarize_paper", "arguments": arguments}
        )

    elif name == "extract_info":
        return await _api_post(
            f"{api}/agent/call", {"tool": "extract_info", "arguments": arguments}
        )

    elif name == "ask_paper":
        return await _api_post(f"{api}/agent/call", {"tool": "ask_paper", "arguments": arguments})

    elif name == "ask_papers":
        return await _api_post(f"{api}/agent/call", {"tool": "ask_papers", "arguments": arguments})

    elif name == "import_paper":
        return await _api_post(
            f"{api}/agent/call", {"tool": "import_paper", "arguments": arguments}
        )

    elif name == "list_collections":
        return await _api_post(
            f"{api}/agent/call", {"tool": "list_collections", "arguments": arguments}
        )

    elif name == "export_citations":
        return await _api_post(
            f"{api}/agent/call", {"tool": "export_citations", "arguments": arguments}
        )

    elif name == "search_evidence":
        return await _api_post(f"{api}/evidence/search", arguments)

    elif name == "verify_claim":
        return await _api_post(f"{api}/claims/verify", arguments)

    elif name == "build_context_pack":
        return await _api_post(f"{api}/agent/context-pack", arguments)

    elif name == "resolve_identifier":
        # Resolve uses the same get_paper tool with the identifier
        return await _api_post(
            f"{api}/agent/call",
            {"tool": "get_paper", "arguments": {"identifier": arguments["identifier"]}},
        )

    # ─── Research Intelligence Tools ──────────────────────────────
    elif name in (
        "synthesize_papers",
        "analyze_research_gaps",
        "extract_methodology",
        "compare_methods",
        "generate_related_work",
        "find_reading_path",
        "search_with_reasoning",
        "build_evidence_map",
        "investigate",
        "extract_experiments",
        "multi_paper_qa",
        "suggest_next_steps",
        "discover_papers",
        "research_pipeline",
        "compare_papers_table",
        "find_papers_by_taxonomy",
        "trace_citations",
        "corpus_overview",
        "extract_all_results",
        "find_contradictions",
        "get_paper_section",
        "rank_papers_for_reading",
        "batch_import",
        "find_experts",
        "temporal_trends",
        "auto_cite",
        "paper_lineage",
        "method_comparison",
        "extract_claims",
        "find_datasets",
        "literature_map",
    ):
        return await _api_post(
            f"{api}/agent/call", {"tool": name, "arguments": arguments}
        )

    else:
        return {"error": f"Unknown tool: {name}"}


# ─── Resource Handlers ──────────────────────────────────────────────────────


@server.list_resources()  # type: ignore[no-untyped-call, untyped-decorator]
async def handle_list_resources() -> list[Resource]:
    """Return available MCP resources."""
    return [
        Resource(
            uri="kaleidoscope://manifest",
            name="Agent Manifest",
            description="Kaleidoscope agent manifest with tool schemas, scopes, and capabilities.",
            mimeType="application/json",
        ),
        Resource(
            uri="kaleidoscope://health",
            name="Service Health",
            description="Current health status of the Kaleidoscope backend service.",
            mimeType="application/json",
        ),
    ]


@server.read_resource()  # type: ignore[no-untyped-call, untyped-decorator]
async def handle_read_resource(uri: str) -> str:
    """Read a Kaleidoscope resource by URI."""
    uri_str = str(uri)

    if uri_str == "kaleidoscope://manifest":
        result = await _api_get("/api/v1/agent/manifest")
        return json.dumps(result, ensure_ascii=False, indent=2)

    elif uri_str == "kaleidoscope://health":
        try:
            result = await _api_get("/health")
            return json.dumps(result, ensure_ascii=False, indent=2)
        except Exception as exc:
            return json.dumps({"status": "unreachable", "error": str(exc)})

    elif uri_str.startswith("kaleidoscope://papers/"):
        paper_id = uri_str.replace("kaleidoscope://papers/", "")
        result = await _api_post(
            "/api/v1/agent/call",
            {"tool": "get_paper", "arguments": {"identifier": paper_id}},
        )
        return json.dumps(result, ensure_ascii=False, indent=2)

    else:
        return json.dumps({"error": f"Unknown resource: {uri_str}"})


# ─── Entrypoint ─────────────────────────────────────────────────────────────


async def main() -> None:
    """Run the MCP server over stdio transport."""
    async with stdio_server() as (read_stream, write_stream):
        await server.run(
            read_stream,
            write_stream,
            server.create_initialization_options(),
        )


if __name__ == "__main__":
    import asyncio

    asyncio.run(main())
